DROP VIEW IF EXISTS replset.vw_orgmapsquare CASCADE;  CREATE OR REPLACE VIEW replset.vw_orgmapsquare AS  SELECT orgm.code,     orgm.rarus_idrref,     orgm.buh_idrref,     orgm.rarus_code,     orgm.buh_code,     orgm.rarus_table,     orgm.buh_table,     orgm.rarus_desc,     orgm.buh_desc,     orgm.shop_index,     store._fld8310 AS square    FROM rarus_buh_orgs_map orgm,     dbo.rarus__reference94 store   WHERE ((store._fld8286rref = orgm.rarus_idrref) AND (store._fld8310 <> (0)::numeric));
